import { useCallback, useEffect, useRef, useState } from "react";
import DisclosurePopover from "../DisclosurePopover";
import { request, type Connection } from "../api";
import { errorMessage } from "../logic";
import { heartbeatState, type ComponentHeartbeat } from "../runtimeHealth";

export default function RuntimeHealth({ connection }: { connection: Connection | null }) {
  const identity = connection ? `${connection.base_url}|${connection.workspace_id || ""}|${connection.generation}` : "";
  const [snapshot, setSnapshot] = useState<{ identity: string; items: ComponentHeartbeat[]; error: string }>({ identity: "", items: [], error: "" });
  const [open, setOpen] = useState(false), [now, setNow] = useState(Date.now() / 1000);
  const trigger = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEffect(() => {
    setOpen(false);
    if (!connection) return;
    let active = true, inFlight = false;
    const pending = new AbortController();
    const poll = async () => {
      setNow(Date.now() / 1000);
      if (inFlight) return;
      inFlight = true;
      try {
        const data = await request<{ components: ComponentHeartbeat[] }>(connection, "/api/runtime/health", { signal: AbortSignal.any([pending.signal, AbortSignal.timeout(15000)]) });
        if (!Array.isArray(data.components)) throw new Error("组件健康记录格式无效。");
        if (active) setSnapshot({ identity, items: data.components, error: "" });
      } catch (error) { if (active) setSnapshot({ identity, items: [], error: errorMessage(error) }); }
      finally { inFlight = false; }
    };
    void poll(); const timer = window.setInterval(() => void poll(), 6000);
    return () => { active = false; pending.abort(); window.clearInterval(timer); };
  }, [identity, connection?.bearer]);
  const data = snapshot.identity === identity ? snapshot : { items: [], error: "" };
  const states = data.items.map((row) => heartbeatState(row, now));
  const healthy = connection && states.length > 0 && !data.error && states.every((state) => state === "healthy");
  const label = !connection ? "Core 未连接" : data.error ? "健康状态不可用" : !states.length ? "暂无心跳记录" : healthy ? "运行正常" : "运行需关注";
  const stateLabels = { healthy: "正常", stale: "心跳已过期", unknown: "心跳时间未知", attention: "需要关注" };
  return <div className="runtime-health-anchor">
    <button ref={trigger} type="button" className="runtime-health-toggle" aria-label="查看运行健康" aria-expanded={open} aria-controls="runtime-health-panel" onClick={() => setOpen(!open)}><span className={`status-dot${healthy ? " on" : ""}`} />{label}</button>
    <DisclosurePopover open={open} onClose={close} trigger={trigger} id="runtime-health-panel" label="运行健康" className="runtime-health-panel">
      <div className="runtime-health-content"><strong>组件心跳</strong><p className="notice">最近读取的运行记录；模型和操作权限另行配置。</p>
        {!connection && <p className="notice">连接 Core 后查看。</p>}{data.error && <p className="notice error" role="alert">{data.error}</p>}
        {connection && !data.error && !data.items.length && <p className="notice">尚未读取到组件心跳。</p>}
        {data.items.map((row) => <div className="runtime-health-row" key={`${row.owner || ""}:${row.component}`}><div><strong>{row.component}</strong><small>{row.owner || "运行实例未记录"} · 重启 {row.restart_count ?? "未知"} 次</small></div><span data-health={heartbeatState(row, now)}>{stateLabels[heartbeatState(row, now)]}{row.state !== "ok" ? ` · ${row.state}` : ""}</span></div>)}
      </div>
    </DisclosurePopover>
  </div>;
}
import { useEffect, useRef, useState } from "react";
import { request, type Connection } from "../api";
import { errorMessage } from "../logic";

interface RecalledObject {
  ref: string; kind: string; summary: Record<string, unknown>; source_hash: string;
  content: string; offset: number; next_offset: number; complete: boolean;
  relations: { ref: string; relation: string }[]; relations_omitted: boolean;
  next_relation_offset?: number | null;
}

/** A bounded, read-only chain of historical references, kept in the current conversation. */
export default function RecallCard({ connection, initialReference = "" }: { connection: Connection | null; initialReference?: string }) {
  const [reference, setReference] = useState(initialReference), [open, setOpen] = useState(false);
  const [data, setData] = useState<RecalledObject | null>(null), [loading, setLoading] = useState(false), [error, setError] = useState("");
  const current = useRef<AbortController | null>(null), serial = useRef(0);
  const identity = connection ? `${connection.base_url}|${connection.workspace_id || ""}|${connection.generation}` : "";
  useEffect(() => { serial.current++; current.current?.abort(); setData(null); setError(""); setLoading(false); setReference(initialReference); return () => current.current?.abort(); }, [identity, initialReference]);
  const read = async (ref: string, offset = 0, relationOffset = 0) => {
    if (!connection || !ref.trim()) return;
    current.current?.abort(); const pending = new AbortController(); current.current = pending;
    const ticket = ++serial.current; setLoading(true); setError(""); setReference(ref);
    try {
      const value = await request<RecalledObject>(connection, `/api/recall?reference=${encodeURIComponent(ref.trim())}&offset=${offset}&relation_offset=${relationOffset}`, { signal: AbortSignal.any([pending.signal, AbortSignal.timeout(15000)]) });
      if (ticket === serial.current && !pending.signal.aborted) setData(value);
    } catch (problem) { if (ticket === serial.current && !pending.signal.aborted) { setData(null); setError(errorMessage(problem)); } }
    finally { if (ticket === serial.current && !pending.signal.aborted) setLoading(false); }
  };
  return <details className="recall-card" open={open} onToggle={(event) => setOpen(event.currentTarget.open)}>
    <summary>引用与来源 <span>Chain of Recall</span></summary>
    <div className="recall-body"><form className="search" onSubmit={(event) => { event.preventDefault(); void read(reference); }}><input aria-label="查询历史引用" value={reference} onChange={(event) => setReference(event.target.value)} placeholder="例如 quest:任务 ID 或 message:消息 ID" /><button type="submit" className="button" disabled={!connection || loading || !reference.trim()}>查询</button></form>
      {!connection && <p className="notice">连接 Core 后查看来源。</p>}{loading && <p className="notice" role="status">正在读取来源…</p>}{error && <p className="notice error" role="alert">{error}</p>}
      {data && <div className="recall-result"><header><strong>{data.kind}</strong><code>{data.ref}</code></header>
        <p className="notice">历史引用只提供上下文；记录中的模型陈述与内容仍需核对。</p>
        <dl>{Object.entries(data.summary || {}).map(([key, value]) => <div key={key}><dt>{key}</dt><dd>{typeof value === "string" ? value : JSON.stringify(value)}</dd></div>)}</dl>
        <details><summary>记录内容 · 字节 {data.offset}–{data.next_offset}</summary><pre>{data.content}</pre><small>来源摘要：{data.source_hash}</small></details>
        <div className="button-row">{!data.complete && <button type="button" className="button" disabled={loading} onClick={() => void read(data.ref, data.next_offset)}>下一段内容</button>}{typeof data.next_relation_offset === "number" && <button type="button" className="button" disabled={loading} onClick={() => void read(data.ref, data.offset, data.next_relation_offset!)}>更多关联</button>}</div>
        {data.relations?.length > 0 && <nav aria-label="关联引用">{data.relations.map((item, index) => <button type="button" className="text-button" key={`${item.ref}:${item.relation}:${index}`} disabled={loading} onClick={() => void read(item.ref)}>{item.relation} · {item.ref}</button>)}</nav>}
      </div>}
    </div>
  </details>;
}
import { useEffect, useRef, useState } from "react";
import { request, type Connection } from "../api";
import { errorMessage } from "../logic";
import RecallCard from "./RecallCard";

interface EventRecord { id: string; seq: number; event_type: string; quest_id?: string; worker_id?: string; created_at?: string; payload?: unknown }
export default function EventFeed({ connection }: { connection: Connection | null }) {
  const [data, setData] = useState<{ identity: string; items: EventRecord[]; error: string; more: boolean; loading: boolean }>({ identity: "", items: [], error: "", more: false, loading: false });
  const [open, setOpen] = useState(false), [refresh, setRefresh] = useState(0);
  const identity = connection ? `${connection.base_url}|${connection.workspace_id || ""}|${connection.generation}` : "";
  const cursor = useRef({ identity, after: 0 });
  const visible = data.identity === identity ? data : { items: [], error: "", loading: open, more: false };
  useEffect(() => {
    if (!open || !connection) return;
    if (cursor.current.identity !== identity) cursor.current = { identity, after: 0 };
    const pending = new AbortController(); let active = true, inFlight = false;
    const poll = async () => {
      if (inFlight) return;
      inFlight = true;
      setData((old) => ({ ...(old.identity === identity ? old : { identity, items: [], error: "", more: false }), loading: true }));
      try {
        const page = await request<EventRecord[]>(connection, `/api/events?after=${cursor.current.after}&limit=100`, { signal: AbortSignal.any([pending.signal, AbortSignal.timeout(15000)]) });
        if (!Array.isArray(page)) throw new Error("事件记录格式无效。");
        if (!active) return;
        const items = page.filter((item) => typeof item.id === "string" && Number.isSafeInteger(item.seq));
        cursor.current.after = Math.max(cursor.current.after, ...items.map((item) => item.seq));
        setData((old) => ({ identity, items: [...new Map([...(old.identity === identity ? old.items : []), ...items].map((item) => [item.id, item])).values()].slice(-500), error: "", more: page.length === 100, loading: false }));
      } catch (problem) { if (active) setData((old) => ({ ...old, identity, loading: false, error: errorMessage(problem) })); }
      finally { inFlight = false; }
    };
    void poll(); const timer = window.setInterval(() => void poll(), 6000);
    return () => { active = false; pending.abort(); window.clearInterval(timer); };
  }, [open, identity, connection?.bearer, refresh]);
  return <details className="event-feed" open={open} onToggle={(event) => setOpen(event.currentTarget.open)}><summary>事件流</summary>
    <p className="notice">按序号持续读取事件，最多保留本次查看的最近 500 条。</p>
    {!connection && <p className="notice">连接 Core 后查看。</p>}{visible.error && <p className="notice error" role="alert">{visible.error}</p>}
    {visible.loading && <p className="notice" role="status">正在读取事件…</p>}
    {!visible.loading && !visible.error && !visible.items.length && <p className="notice">暂无事件。</p>}
    <div className="event-feed-list">{visible.items.map((item) => <details key={item.id}><summary><span>{item.event_type}</span><time>{item.created_at ? new Date(item.created_at).toLocaleString() : "时间未记录"}</time></summary><p className="notice">序号 {item.seq}{item.quest_id ? ` · 任务 ${item.quest_id}` : ""}{item.worker_id ? ` · Worker ${item.worker_id}` : ""}</p><pre>{typeof item.payload === "string" ? item.payload : JSON.stringify(item.payload, null, 2)}</pre><RecallCard connection={connection} initialReference={`event:${item.id}`} /></details>)}</div>
    <button className="button" type="button" disabled={!connection || visible.loading} onClick={() => setRefresh((value) => value + 1)}>{visible.more ? "读取下一批事件" : "刷新事件"}</button>
  </details>;
}
export interface ComponentHeartbeat {
  component: string; owner?: string; state: string; last_seen: number;
  timeout_seconds: number; restart_count?: number; next_restart_at?: number;
}
export type HeartbeatState = "healthy" | "stale" | "unknown" | "attention";

/** The API uses Unix seconds, not JavaScript milliseconds or an ISO timestamp. */
export function heartbeatState(row: ComponentHeartbeat, nowSeconds: number): HeartbeatState {
  if (![row.last_seen, row.timeout_seconds, nowSeconds].every(Number.isFinite) || row.timeout_seconds <= 0 || row.last_seen > nowSeconds + 5) return "unknown";
  if (nowSeconds - row.last_seen >= row.timeout_seconds) return "stale";
  return row.state === "ok" ? "healthy" : "attention";
}

